/// <reference path="../References.d.ts"/>
export const SYNC = 'zone.sync';
export const SYNC_NAMES = 'zone.sync_names';
export const TRAVERSE = 'zone.traverse';
export const FILTER = 'zone.filter';
export const CHANGE = 'zone.change';

export interface Zone {
	id?: string;
	datacenter?: string;
	name?: string;
	comment?: string;
	dns_servers?: string[];
	dns_servers6?: string[];
	announce_rate?: number;
	startup_rate?: number;
}

export interface Filter {
	id?: string;
	name?: string;
	comment?: string;
}

export type Zones = Zone[];

export type ZoneRo = Readonly<Zone>;
export type ZonesRo = ReadonlyArray<ZoneRo>;

export interface ZoneDispatch {
	type: string;
	data?: {
		id?: string;
		zone?: Zone;
		zones?: Zones;
		page?: number;
		pageCount?: number;
		filter?: Filter;
		count?: number;
	};
}
